import{_ as d,o as t,c as o,ag as a}from"./chunks/framework.CPvOxTBX.js";const m=JSON.parse('{"title":"词条内链接","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/dictionary-links.md","filePath":"zh/guide/dictionary-links.md","lastUpdated":1793489430000}'),c={name:"zh/guide/dictionary-links.md"};function r(i,e,n,l,h,s){return t(),o("div",null,e[0]||(e[0]=[a('<h1 id="词条内链接" tabindex="-1">词条内链接 <a class="header-anchor" href="#词条内链接" aria-label="Permalink to &quot;词条内链接&quot;">​</a></h1><p>词悦遵循 MDict 与 GoldenDict 词典已有的链接约定。本文列出支持的写法，以及 词悦额外增加的一个转义规则。</p><h2 id="词条链接" tabindex="-1">词条链接 <a class="header-anchor" href="#词条链接" aria-label="Permalink to &quot;词条链接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>链接</th><th>跳转目标</th></tr></thead><tbody><tr><td><code>entry://word</code></td><td>词条 <code>word</code></td></tr><tr><td><code>bword://word</code></td><td>与 <code>entry://word</code> 相同（Babylon 写法）</td></tr><tr><td><code>entry://word#anchor</code></td><td>词条 <code>word</code>，并滚动到 <code>anchor</code> 位置</td></tr><tr><td><code>entry://#anchor</code></td><td>当前已显示的词条，滚动到 <code>anchor</code> 位置</td></tr><tr><td><code>entry://word##anchor</code></td><td>名字就是 <code>word#anchor</code> 的词条</td></tr></tbody></table><p><code>bword://</code> 的行为与 <code>entry://</code> 完全一致，上表每一种写法都有对应的 <code>bword://</code> 形式。</p><h2 id="词条名本身含" tabindex="-1">词条名本身含 <code>#</code> <a class="header-anchor" href="#词条名本身含" aria-label="Permalink to &quot;词条名本身含 `#`&quot;">​</a></h2><p>单个 <code>#</code> 永远用来分隔词条名与锚点。因此，词条名本身含 <code>#</code> 时必须写成两个 <code>#</code> 来转义：</p><table tabindex="0"><thead><tr><th>词条名</th><th>写法</th></tr></thead><tbody><tr><td><code>tag#sumeru</code></td><td><code>entry://tag##sumeru</code></td></tr></tbody></table><p>转义与分隔可以组合使用：<code>entry://tag##sumeru#x</code> 打开词条 <code>tag#sumeru</code> 并滚动到 <code>x</code>；<code>entry://tag###sumeru</code> 则打开词条 <code>tag#</code> 并滚动到 <code>sumeru</code>。</p><p>这个转义规则是词悦特有的。GoldenDict-ng 同样在 <code>#</code> 处切分，但它没有办法定位到 名字含 <code>#</code> 的词条。</p><h2 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h2><ul><li>锚点只负责滚动，不进入浏览历史：返回时不会再次触发滚动。</li><li>不含词条名的链接只滚动当前词条，不会发起查词。</li><li>锚点会同时匹配 <code>id</code> 与 <code>name</code> 属性，两种写法都能定位。</li><li>锚点属于链接所在词典的词条：同组内其他词典即使也有这个词条，也不会替它滚动。</li></ul><h2 id="音频与视频" tabindex="-1">音频与视频 <a class="header-anchor" href="#音频与视频" aria-label="Permalink to &quot;音频与视频&quot;">​</a></h2><p>音频引用沿用 MDict 的写法 <code>&lt;a href=&quot;sound://file.mp3&quot;&gt;…&lt;/a&gt;</code>，从词典的 <code>.mdd</code> 或 StarDict 的 <code>res/</code> 资源中播放。</p><h2 id="背景与原理" tabindex="-1">背景与原理 <a class="header-anchor" href="#背景与原理" aria-label="Permalink to &quot;背景与原理&quot;">​</a></h2><p>关于这些规则背后的缘由——GoldenDict-ng、MDict、Babylon 各自如何处理每种 scheme、<code>gdlookup://localhost</code> 为何存在、以及词悦在何处更进一步——见 <a href="./dictionary-link-schemes.html">词典链接 Scheme 原理解析</a>。</p>',16)]))}const p=d(c,[["render",r]]);export{m as __pageData,p as default};
